//
// Provider mapping engine for resource facts (ADR-0073): Cloudflare and Google.
//
// What is read is DATA: `mappings/<provider>.json` names, per resource type,
// the attribute paths to copy, the ids kept as join keys, the nested lists, and
// the relations. At load each mapping is validated against ITS OWN vendored
// projection of the provider's published schema (`spec/<provider>.schema.json`,
// generated by scripts/gen-facts-spec.mjs): an unknown or sensitive attribute,
// or a non-scalar read, stops the module from loading. Anything the mapping
// does not name is never read: not a Worker's source, a binding's value, a
// tunnel secret. `pickPublic` then drops any named attribute the document
// itself marks sensitive.
//
// Relations are exact value equality on mapped join attributes. A value that
// matches nothing resolves to null; nothing is guessed by name. In a PLAN
// document only, a relation the values cannot resolve (the value is unknown
// until apply) may resolve through the configuration's references, and only
// when exactly one referenced address has the target type.

import { readFileSync } from "node:fs";

import { makeFact, pickPublic } from "./facts.mjs";
import { validateMapping } from "./validate.mjs";

const readJson = (rel) => JSON.parse(readFileSync(new URL(rel, import.meta.url), "utf8"));

export const CLOUDFLARE_MAPPING = Object.freeze(readJson("./mappings/cloudflare.json"));
export const CLOUDFLARE_SPEC = Object.freeze(readJson("./spec/cloudflare.schema.json"));
validateMapping(CLOUDFLARE_MAPPING, CLOUDFLARE_SPEC);
export const GOOGLE_MAPPING = Object.freeze(readJson("./mappings/google.json"));
export const GOOGLE_SPEC = Object.freeze(readJson("./spec/google.schema.json"));
validateMapping(GOOGLE_MAPPING, GOOGLE_SPEC);

/** Every mapping, with the source name its facts carry. */
const MAPPINGS = [CLOUDFLARE_MAPPING, GOOGLE_MAPPING];
const SOURCE_OF = new WeakMap();
for (const mapping of MAPPINGS) {
  for (const entry of Object.values(mapping.types)) SOURCE_OF.set(entry, `terraform:${mapping.provider.split("/").pop()}`);
}

const WORKER_TYPE = "cloudflare_workers_script";
const BINDING_RELATIONS = CLOUDFLARE_MAPPING.bindingRelations;

/**
 * Own-property lookups only. A resource or binding type comes from the
 * document, and `toString` or `constructor` must not find Object.prototype.
 */
const own = (table, key) => (typeof key === "string" && Object.hasOwn(table, key) ? table[key] : undefined);
const relationsFor = (binding) => own(BINDING_RELATIONS, binding?.type) ?? [];
/** The mapping entry for a resource type, or undefined when no mapping has it. */
export const mappedType = (type) => {
  for (const mapping of MAPPINGS) {
    const entry = own(mapping.types, type);
    if (entry) return entry;
  }
  return undefined;
};
/** Fact types that count as a Worker when a relation targets a Worker script. */
const WORKER_FACT_TYPES = new Set([WORKER_TYPE, "wrangler_worker", "cloudflare_worker"]);
/** Fact types whose NAME is the Worker's script name. */
const NAME_IS_SCRIPT_NAME = new Set(["wrangler_worker", "cloudflare_worker"]);

const getPath = (obj, path) => path.split(".").reduce((o, k) => (o && typeof o === "object" ? o[k] : undefined), obj);

function pickPath(values, sensitive, path) {
  const parts = path.split(".");
  const key = parts.pop();
  const v = parts.length ? getPath(values, parts.join(".")) : values;
  const s = parts.length ? getPath(sensitive, parts.join(".")) : sensitive;
  return pickPublic(v, s, [key])[key];
}

/** The ONE generic importer: a resource of a mapped type in, a fact out. */
export function importResource(resource, entry, references) {
  const { values, sensitive } = resource;
  const attrs = {};
  for (const path of entry.read ?? []) {
    const value = pickPath(values, sensitive, path);
    if (value !== undefined) attrs[path] = value;
  }
  attrs.ids = {};
  for (const path of entry.ids ?? []) {
    const value = pickPath(values, sensitive, path);
    if (value !== undefined) attrs.ids[path] = value;
  }
  for (const list of entry.lists ?? []) {
    const key = list.path.split(".").pop();
    const rows = getPath(values, list.path);
    const markers = getPath(sensitive, list.path);
    attrs[key] = [];
    if (!Array.isArray(rows)) continue;
    // A well-formed document gives a list either no marker or an array with
    // one marker per row. `true` means the whole list is sensitive. Any other
    // shape is malformed, and is treated the same way: the list is withheld
    // and the report says so.
    if (markers !== undefined && !Array.isArray(markers)) {
      attrs[`${key}Withheld`] = true;
      continue;
    }
    rows.forEach((row, index) => {
      if (!row || typeof row !== "object") return;
      let marker;
      if (Array.isArray(markers)) {
        // A row with no marker of its own (a marker list shorter than the
        // rows) is not known to be public, so it is withheld.
        if (index >= markers.length) { attrs[`${key}Withheld`] = true; return; }
        marker = markers[index];
      }
      const picked = pickPublic(row, marker, list.read);
      if (Object.keys(picked).length > 0) attrs[key].push(picked);
    });
  }
  // Configuration references (plan documents), for the attributes the mapping names only.
  const kept = {};
  for (const attr of entry.referenceAttrs ?? []) {
    const addresses = references && Object.hasOwn(references, attr) ? references[attr] : undefined;
    if (Array.isArray(addresses) && addresses.length) kept[attr] = addresses;
  }
  if (Object.keys(kept).length) attrs.references = kept;
  const named = entry.name === undefined ? undefined : pickPath(values, sensitive, entry.name);
  return makeFact({
    source: SOURCE_OF.get(entry) ?? "terraform:cloudflare",
    address: resource.address,
    type: resource.type,
    name: typeof named === "string" ? named : resource.name,
    attrs,
  });
}

/** Resource type → mapping entry. A type not listed here produces no fact. */
export const CLOUDFLARE_TYPES = CLOUDFLARE_MAPPING.types;

/** The value a fact exposes for a mapped join attribute, or undefined. */
function joinValue(fact, attr) {
  const entry = mappedType(fact.type);
  if (fact.attrs.ids?.[attr] !== undefined) return fact.attrs.ids[attr];
  if (fact.attrs[attr] !== undefined) return fact.attrs[attr];
  if (entry?.name === attr || (NAME_IS_SCRIPT_NAME.has(fact.type) && attr === "script_name")) return fact.name || undefined;
  return undefined;
}

function resolveOne(value, relation, facts) {
  if (typeof value !== "string" && typeof value !== "number") return null;
  return joinIndex(facts, relation).get(value) ?? null;
}

/**
 * value → first fact, for one relation over one facts array. Built once per
 * (facts, relation) and reused, so resolving N bindings is not N scans.
 */
const JOIN_INDEXES = new WeakMap();
function joinIndex(facts, relation) {
  let perFacts = JOIN_INDEXES.get(facts);
  if (!perFacts) JOIN_INDEXES.set(facts, (perFacts = new Map()));
  const key = `${relation.toType}\u0000${relation.toAttr}`;
  let index = perFacts.get(key);
  if (!index) {
    index = new Map();
    const types = relation.toType === WORKER_TYPE ? WORKER_FACT_TYPES : new Set([relation.toType]);
    for (const fact of facts) {
      if (!types.has(fact.type)) continue;
      const value = joinValue(fact, relation.toAttr);
      if (value !== undefined && !index.has(value)) index.set(value, fact);
    }
    perFacts.set(key, index);
  }
  return index;
}

const ADDRESS_INDEXES = new WeakMap();
function factAt(facts, address) {
  let index = ADDRESS_INDEXES.get(facts);
  if (!index) ADDRESS_INDEXES.set(facts, (index = new Map(facts.map((f) => [f.address, f]))));
  return index.get(address) ?? null;
}

/**
 * The fact a PLAN's configuration says `fact.<attr>` references, when exactly
 * one referenced address has the relation's target type. Zero or several
 * candidates give null: one is never picked.
 */
function resolveByReference(fact, relation, facts) {
  const candidates = (fact.attrs.references?.[relation.attr] ?? []).filter((a) => a.split(".")[0] === relation.toType);
  if (candidates.length !== 1) return null;
  const target = factAt(facts, candidates[0]);
  return target && target.type === relation.toType ? target : null;
}

/**
 * Resolve a resource's mapped relations. Returns `[{attr, value, to: fact | null}]`;
 * `null` means "not in this document". Order: exact value equality; then, only
 * when `kind` is "plan" and the value resolved nothing, the configuration's
 * references (see resolveByReference). A state document never uses references.
 */
export function resolveRelations(fact, facts, kind) {
  const entry = mappedType(fact.type);
  return (entry?.relations ?? []).map((relation) => {
    const value = joinValue(fact, relation.attr);
    let to = resolveOne(value, relation, facts);
    if (!to && kind === "plan") to = resolveByReference(fact, relation, facts);
    return { attr: relation.attr, value, to };
  });
}

/** Resolve a Worker binding through the mapping's binding relations. */
export function resolveBinding(binding, facts) {
  for (const relation of relationsFor(binding)) {
    const to = resolveOne(binding[relation.attr], relation, facts);
    if (to) return { value: binding[relation.attr], to };
  }
  const first = relationsFor(binding)[0];
  return { value: first ? binding[first.attr] : undefined, to: null };
}

/** True when a binding names another workload (as opposed to storage or config). */
export function isWorkloadBinding(binding) {
  return relationsFor(binding).some((r) => r.toType === WORKER_TYPE);
}

/** The workload a workload-binding names, or "" when the document does not say. */
export function bindingTarget(binding) {
  const relation = relationsFor(binding).find((r) => r.toType === WORKER_TYPE);
  return relation ? (binding[relation.attr] ?? "") : "";
}
